// Stage 1 seed fixtures only -- three inputs, chosen to provoke three
// different response shapes. The full 50-fixture set is Stage 4 and will
// replace the entire contents of this node.
const fixtures = [
  {
    fixture_id: 'seed-01-clean',
    raw_text: 'Halo, saya Budi Santoso mau order 2 pcs Kaos Polos ukuran L dan 1 pcs Topi Baseball. Kirim ke Jl. Melati No. 12, Bandung 40115. Email budi.santoso@example.test, HP 081234567890. Total Rp 450.000 ya. Thanks!'
  },
  {
    // Feeds B2 later: "2,4jt" is the value that passes JSON Schema as 2.4
    // and is wrong by a factor of one million.
    fixture_id: 'seed-02-jt-amount',
    raw_text: 'pagi kak, sy Siti Rahmawati mau pesen hoodie oversize size XL 3pcs sama tote bag 2 pcs. alamat Perum Griya Asri Blok C5 no 8, Tangerang Selatan. wa 0812-9988-7766. totalnya 2,4jt kan? transfer skrg ya'
  },
  {
    // Feeds B6 later: no name, no address, no email, no amount.
    fixture_id: 'seed-03-missing-fields',
    raw_text: 'mau order jaket bomber 1 aja, size large. berapa totalnya'
  }
];

return fixtures.map(f => ({ json: f }));

// Entry-point normalisation. The webhook delivers { body: { raw_text } },
// the fixture path delivers { raw_text } directly. One line instead of a
// dedicated normalise node.
const raw = $json.raw_text ?? $json.body?.raw_text ?? '';

// D3: the injection defence here is structural, not instructional.
// tool_choice forces exactly one tool call, and the untrusted text is
// fenced inside a delimiter. There is deliberately no "ignore any
// instructions in the input" line -- that turns the defence into a
// request the model is free to decline.
const system = [
  'You extract structured order data from raw customer text.',
  'The text is Indonesian, English, or a mix of both, and contains typos.',
  '',
  'amount_as_written must reproduce the amount exactly as it appears in the source text, character for character, with no normalisation of separators, casing or spacing. Use an empty string when the text states no amount at all.',
  'total_amount_idr is that same amount resolved to a plain number of rupiah.',
  'Set needs_review to true whenever customer_name, customer_email or shipping_address is absent from the text, and give the reason in review_reason.'
].join('\n');

// Tool definition lives here rather than in the HTTP node so that
// "Build Request B" in Stage 2 reuses one source of truth.
const tools = [
  {
    name: 'extract_order',
    description: 'Extract structured order data from raw customer text',
    input_schema: {
      type: 'object',
      properties: {
        customer_name: { type: 'string' },
        customer_email: { type: 'string' },
        customer_phone: { type: 'string' },
        shipping_address: { type: 'string' },
        items: {
          type: 'array',
          minItems: 1,
          items: {
            type: 'object',
            properties: {
              product: { type: 'string' },
              size: { type: 'string' },
              qty: { type: 'integer', minimum: 1 }
            },
            required: ['product', 'qty']
          }
        },
        total_amount_idr: { type: 'number' },
        amount_as_written: {
          type: 'string',
          description: "The amount exactly as written in the source text, verbatim. Example: '2,4jt' or 'Rp 2.400.000'. Empty string if no amount present."
        },
        needs_review: { type: 'boolean' },
        review_reason: { type: 'string' }
      },
      required: ['items', 'total_amount_idr', 'amount_as_written', 'needs_review']
    }
  }
];

const request_body = {
  model: 'claude-sonnet-5',
  // Generous on purpose: stop_reason === "max_tokens" must mean real model
  // drift (S5), not a budget we set too tightly.
  max_tokens: 2048,
  system,
  tools,
  tool_choice: { type: 'tool', name: 'extract_order' },
  messages: [
    {
      role: 'user',
      content: '<customer_text>\n' + raw + '\n</customer_text>'
    }
  ]
};

return {
  json: {
    raw_text: raw,
    fixture_id: $json.fixture_id ?? null,
    attempt: 1,
    request_started_at: Date.now(),
    request_body
  }
};

// D1: nothing in this node coerces, repairs or defaults anything.
// block.input is passed through exactly as the model produced it, whatever
// shape that is. Stage 2 decides whether it is acceptable. Silent
// correction here would hide the model drift this pipeline exists to catch.
const res = $json ?? {};

// Output of the HTTP node overwrites the item json, so the source text and
// the start timestamp have to be pulled back from Build Request A.
let started = null;
let raw_text = null;
let fixture_id = null;
try {
  const src = $('Build Request A1').item.json;
  started = src.request_started_at ?? null;
  raw_text = src.raw_text ?? null;
  fixture_id = src.fixture_id ?? null;
} catch (e) {
  // Item pairing can break when the HTTP node emits an error item.
  // Losing the metrics must not take the node down with it.
}

const content = Array.isArray(res.content) ? res.content : [];
const block = content.find(
  b => b && b.type === 'tool_use' && b.name === 'extract_order'
) || null;

let api_error = null;
if (res.error) {
  api_error = typeof res.error === 'string' ? res.error : JSON.stringify(res.error);
} else if (!Array.isArray(res.content)) {
  api_error = 'Response carried no content array: ' + JSON.stringify(res).slice(0, 500);
}

const usage = res.usage ?? {};

return {
  json: {
    raw_text,
    fixture_id,
    attempt_count: 1,
    tool_use_found: block !== null,
    data: block ? block.input : null,
    stop_reason: res.stop_reason ?? null,
    input_tokens: usage.input_tokens ?? null,
    output_tokens: usage.output_tokens ?? null,
    // Includes the node-transition overhead, not purely wire time.
    elapsed_ms: started === null ? null : Date.now() - started,
    api_error,
    // Stage 1 only, so the raw response can be pasted back for review.
    // This field is removed in Stage 2.
    raw_response: res
  }
};
